import sys, itertools, time
n=22
# map edge to var 1..m
edge_var={}
vars=[]
idx=1
for i in range(n):
    for j in range(i+1,n):
        edge_var[(i,j)]=idx; idx+=1
clauses=[]
for comb in itertools.combinations(range(n),4):
    es=[]
    for a,b in itertools.combinations(comb,2): es.append(edge_var[(a,b)])
    clauses.append(es) # at least one blue
for comb in itertools.combinations(range(n),5):
    es=[]
    for a,b in itertools.combinations(comb,2): es.append(-edge_var[(a,b)])
    clauses.append(es) # at least one red
print(n, idx-1, len(clauses))
try:
    import pycosat
    t=time.time(); sol=pycosat.solve(clauses, verbose=0); print('pycosat', time.time()-t, type(sol), sol if isinstance(sol,str) else len(sol))
    if isinstance(sol,list):
        bits=[1 if sol[i-1]>0 else 0 for i in range(1,idx)]
        print(bits)
except Exception as e: print('pycosat err', repr(e))
try:
    from pysat.solvers import Glucose3
    t=time.time(); s=Glucose3(bootstrap_with=clauses); print('created')
    res=s.solve(); print('pysat', res, time.time()-t)
    if res:
       model=s.get_model(); arr=[0]*(idx)
       for lit in model:
          if abs(lit)<idx: arr[abs(lit)]= 1 if lit>0 else 0
       bits=[arr[i] for i in range(1,idx)]
       print(bits)
except Exception as e: print('pysat err', repr(e))

